package wire

import "embed"

//go:generate go run gen_copy.go

// schemaAssets carries a build-time copy of the canonical exec-channel schema.
// The copy under schema/ is regenerated by `go generate` (gen_copy.go) from the
// repo-root contracts/exec/exec-channel.schema.json and is byte-identical to it
// (CI asserts with cmp). It is embedded so conformance tests load the schema
// hermetically, with no dependence on the working directory.
//
//go:embed schema/exec-channel.schema.json
var schemaAssets embed.FS

// fixtureAssets carries the shared golden fixtures, copied byte-for-byte from
// contracts/exec/testdata/ by the same generate step. The same bytes feed the
// Go and Rust conformance suites, which is what makes the cross-language
// equivalence proof hold.
//
//go:embed all:testdata
var fixtureAssets embed.FS

// controlSchemaAssets carries a build-time copy of the canonical control-RPC
// schema, regenerated by the same generate step from
// contracts/control/control-rpc.schema.json and byte-identical to it (CI asserts
// with cmp). The control schema lives beside the exec schema under schema/.
//
//go:embed schema/control-rpc.schema.json
var controlSchemaAssets embed.FS

// controlFixtureAssets carries the control-RPC golden fixtures, copied
// byte-for-byte from contracts/control/testdata/ into a SEPARATE testdata-control/
// subtree so the exec invalid-fixture sweep does not pick up control fixtures.
// The same bytes feed the Go and Rust control conformance suites.
//
//go:embed all:testdata-control
var controlFixtureAssets embed.FS
